extern vec2 texSize;
extern vec2 origin;
extern number mode;
extern number fillV;
extern number band;
extern number phase;
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
  vec4 p = Texel(tex, tc);
  if (p.a < 0.02) return vec4(0.0);
  vec2 c = floor(tc * texSize) - origin;
  float l = dot(p.rgb, vec3(0.299, 0.587, 0.114));
  vec3 rgb = color.rgb;
  float a = 0.0;
  if (mode < 1.5) {
    rgb = vec3(min(1.0, l * 1.12 + 0.03), min(1.0, l * 0.94 + 0.015), l * 0.66);
    a = c.y >= fillV ? 1.0 : 0.0;
  } else if (mode < 2.5) {
    float d = abs(c.x - band);
    a = d < 1.0 ? 1.0 : (d < 2.0 ? 0.45 : 0.0);
  } else {
    if (mod(c.y + phase, 5.0) < 1.0) { a = 1.0; }
    else { rgb = vec3(l); a = 0.3; }
  }
  // (its dark outline stays as it is: light never leaves the body)
  if (mode > 1.5) a *= smoothstep(0.17, 0.27, l);
  return vec4(rgb, a * p.a * color.a);
}

extern vec2 texSize;
extern vec4 frame;
extern number time;
extern number mode;
extern number flameMax;
extern number gray;
extern vec2 rows;
extern vec2 centre;
extern vec3 cInk;
extern vec3 cShade;
extern vec3 cDeep;
extern vec3 cViolet;
extern vec3 cBright;
float solid(Image tex, vec2 c) {
  if (c.x < 0.0 || c.y < 0.0 || c.x >= frame.z || c.y >= frame.w) return 0.0;
  return step(0.02, Texel(tex, (frame.xy + c + 0.5) / texSize).a);
}
float hash2(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }
float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash2(i), hash2(i + vec2(1.0, 0.0)), f.x),
             mix(hash2(i + vec2(0.0, 1.0)), hash2(i + vec2(1.0, 1.0)), f.x), f.y);
}
// How many cells above the body this cell is (the body straight below
// or one column aside), 0 past flameMax.
float above(Image tex, vec2 c) {
  for (int j = 1; j <= 12; j++) {
    float fj = float(j);
    if (fj > flameMax) break;
    float s = solid(tex, c + vec2(0.0, fj));
    s = max(s, solid(tex, c + vec2(-1.0, fj)));
    s = max(s, solid(tex, c + vec2(1.0, fj)));
    if (s > 0.5) return fj;
  }
  return 0.0;
}
// The shadow fire at a cell (<= 0: none): dense by the body, ragged
// higher up and broken into puffs that rise and thin away.
float fire(Image tex, vec2 c) {
  if (flameMax < 0.5 || solid(tex, c) > 0.5) return -1.0;
  float d = above(tex, c);
  if (d < 0.5) return -1.0;
  float heat = 1.0 - (d - 1.0) / flameMax;
  float n = vnoise(vec2(c.x * 0.8, (c.y + time * 3.2) * 0.42));
  float m = vnoise(vec2(c.x * 1.1 + 7.0, (c.y + time * 4.4) * 0.7));
  return heat - (1.0 - n) * 0.7 - (1.0 - m) * 0.25;
}
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
  vec2 c = floor(tc * texSize) - frame.xy;
  float self = solid(tex, c);
  float inner = 0.0;
  float outer = 0.0;
  for (int iy = -2; iy <= 2; iy++) {
    for (int ix = -2; ix <= 2; ix++) {
      float fx = float(ix);
      float fy = float(iy);
      if (abs(fx) + abs(fy) < 3.5) {
        float s = solid(tex, c + vec2(fx, fy));
        if (abs(fx) < 1.5 && abs(fy) < 1.5) inner = max(inner, s);
        outer = max(outer, s);
      }
    }
  }
  // the rims thin away over the last rows down to the feet
  float feet = clamp((rows.x - c.y) / 6.0, 0.0, 1.0);
  vec3 rgb = vec3(0.0);
  float a = 0.0;
  bool giant = mode > 2.5 && mode < 3.5;
  if (giant && self > 0.5) {
    // the colossus: its own shading sunk into the dark, fading into
    // the ground at its feet
    vec4 p = Texel(tex, (frame.xy + c + 0.5) / texSize);
    float l = dot(p.rgb, vec3(0.299, 0.587, 0.114));
    rgb = mix(cShade, cDeep, clamp(l * 1.4, 0.0, 1.0));
    a = 0.55 * clamp((rows.x - c.y) / 10.0, 0.1, 1.0);
  } else if (self > 0.5) {
    return vec4(0.0);
  } else if (mode < 0.5 || giant) {
    float v = fire(tex, c);
    if (v > 0.0) {
      if (v < 0.16) {
        rgb = cViolet; a = 0.9;
        float m = vnoise(vec2(c.x * 1.3 + 3.0, (c.y + time * 3.2) * 0.5));
        if (m > 0.75) rgb = cBright;
      } else if (v < 0.36) { rgb = cDeep; a = 0.88; }
      else if (v < 0.6) { rgb = cShade; a = 0.86; }
      else { rgb = cInk; a = 0.84; }
    } else if (inner > 0.5) {
      rgb = giant ? cViolet : cDeep;
      a = (giant ? 0.8 * clamp((rows.x - c.y) / 10.0, 0.1, 1.0) : 0.75 * feet);
    }
  } else if (mode < 1.5) {
    // the domain: the shadow climbing the legs, fading up
    float k = clamp(1.0 - (rows.y - c.y) / 7.0, 0.0, 1.0);
    if (inner > 0.5) { rgb = cViolet; a = 0.85 * k; }
    else if (outer > 0.5) { rgb = cInk; a = 0.5 * k; }
  } else if (mode < 2.5) {
    // the authority: a quiet violet rim, two lights crawling round it
    float ang = atan(c.y + 0.5 - centre.y, c.x + 0.5 - centre.x);
    float d1 = abs(mod(ang - time * 1.6 + 3.14159, 6.28318) - 3.14159);
    float d2 = abs(mod(ang + time * 1.25 - 2.0 + 3.14159, 6.28318) - 3.14159);
    float dm = min(d1, d2);
    if (inner > 0.5) {
      if (dm < 0.3) { rgb = cBright; a = 0.95; }
      else if (dm < 0.6) { rgb = cViolet; a = 0.92; }
      else { rgb = cDeep; a = 0.7 * feet; }
    } else if (outer > 0.5 && dm < 0.45) { rgb = cDeep; a = 0.6; }
  } else {
    if (inner > 0.5) { rgb = cViolet; a = 0.5 * feet; }
  }
  float g = dot(rgb, vec3(0.299, 0.587, 0.114));
  rgb = mix(rgb, vec3(g), gray);
  return vec4(rgb, a * color.a);
}

extern vec3 dark;
extern vec3 light;
extern number cutV;
vec4 effect(vec4 color, Image tex, vec2 uv, vec2 sc) {
  vec4 p = Texel(tex, uv);
  if (uv.y > cutV) return vec4(0.0);
  float l = dot(p.rgb, vec3(0.299, 0.587, 0.114));
  return vec4(mix(dark, light, clamp(l * 1.35, 0.0, 1.0)), p.a * color.a);
}

extern vec3 soulTint;
vec4 effect(vec4 color, Image tex, vec2 uv, vec2 screen) {
  vec4 p=Texel(tex,uv);
  float light=dot(p.rgb,vec3(.299,.587,.114));
  return vec4(soulTint*(.65+.35*light),p.a*color.a);
}

extern number u_time;
extern vec3 u_c0;
extern vec3 u_c1;
extern vec3 u_c2;
extern number u_deep;
vec4 effect(vec4 color, Image tex, vec2 uv, vec2 sc) {
  float across = 1.0 - abs(uv.x * 2.0 - 1.0);
  float soft = across * across * (3.0 - 2.0 * across);
  float w = clamp(sin(uv.y * 9.0 - u_time * 2.2) * 1.6 - 0.6, 0.0, 1.0);
  vec3 rgb = mix(mix(u_c0, u_c1, w * 0.8), u_c2, soft * soft * soft * 0.25);
  rgb = mix(rgb, rgb * rgb, u_deep);
  float streak = 0.72 + 0.28 * sin(uv.y * 48.0 + u_time * 3.0);
  return vec4(rgb, color.a * soft * streak);
}

extern number u_time;
vec3 hue3(float h) {
  vec3 k = abs(fract(vec3(h) + vec3(0.0, 0.6666667, 0.3333333)) * 6.0 - 3.0) - 1.0;
  return clamp(k, 0.0, 1.0);
}
vec4 effect(vec4 color, Image tex, vec2 uv, vec2 sc) {
  float across = 1.0 - abs(uv.x * 2.0 - 1.0);
  float soft = across * across * (3.0 - 2.0 * across);
  vec3 rgb = mix(hue3(uv.y * 0.55 - u_time * 0.22) * 0.8 + 0.2, vec3(1.0), 0.15 + 0.4 * soft * soft * soft);
  float streak = 0.72 + 0.28 * sin(uv.y * 48.0 + u_time * 3.0);
  return vec4(rgb, color.a * soft * streak);
}

vec4 effect(vec4 color, Image tex, vec2 uv, vec2 sc) {
  return vec4(color.rgb, color.a * Texel(tex, uv).a);
}

extern vec4 frameUV;
extern float rows;
extern float band;
extern float width;
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
  float a = Texel(tex, tc).a;
  float fy = (tc.y - frameUV.y) / frameUV.w;
  float up = 1.0 - (floor(fy * rows) + 0.5) / rows;
  float k = clamp(1.0 - abs(up - band) / width, 0.0, 1.0);
  return vec4(color.rgb, a * k * k * color.a);
}

extern vec2 texelSize;
extern vec4 frameBounds;
extern vec4 rimColor;
extern vec4 haloColor;
float spriteAlpha(Image tex, vec2 p) {
  if (p.x < frameBounds.x || p.y < frameBounds.y ||
      p.x >= frameBounds.z || p.y >= frameBounds.w) return 0.0;
  return Texel(tex, p).a;
}
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
  float centre = spriteAlpha(tex, tc);
  float inner = 0.0;
  float outer = 0.0;
  // Float offsets: the game renders through ANGLE (GLSL ES), which
  // has no integer abs() -- an int abs() here failed to compile there
  // and the outline silently fell back to the faint max-blended one.
  for (int iy = -2; iy <= 2; iy++) {
    for (int ix = -2; ix <= 2; ix++) {
      float fx = float(ix);
      float fy = float(iy);
      if (abs(fx) + abs(fy) < 3.5) {
        float sampleAlpha = spriteAlpha(tex, tc + vec2(fx, fy) * texelSize);
        if (abs(fx) < 1.5 && abs(fy) < 1.5) inner = max(inner, sampleAlpha);
        outer = max(outer, sampleAlpha);
      }
    }
  }
  float ia = max(0.0, inner - centre) * rimColor.a;
  float oa = max(0.0, outer - max(inner, centre)) * haloColor.a;
  float alpha = ia + oa * (1.0 - ia);
  vec3 rgb = (rimColor.rgb * ia + haloColor.rgb * oa * (1.0 - ia)) / max(alpha, 0.00001);
  return vec4(rgb, alpha);
}

vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
  float a = Texel(tex, tc).a * color.a;
  return vec4(color.rgb * a, a);
}

vec4 effect(vec4 color, Image tex, vec2 uv, vec2 sc) {
  return vec4(color.rgb, color.a * Texel(tex, uv).a);
}

vec4 effect(vec4 color, Image tex, vec2 uv, vec2 sc) {
  float a = Texel(tex, uv).a;
  return vec4(color.rgb * a, a) * color.a;
}

vec4 effect(vec4 color, Image tex, vec2 uv, vec2 sc) {
  return vec4(color.rgb, color.a * step(0.5, Texel(tex, uv).a));
}

uniform vec2 texel;
uniform vec4 frame;
float alphaAt(Image tex, vec2 q) {
  if (q.x < frame.x || q.y < frame.y || q.x > frame.z || q.y > frame.w) return 0.0;
  return Texel(tex, q).a;
}
vec4 effect(vec4 color, Image tex, vec2 uv, vec2 sc) {
  if (alphaAt(tex, uv) > 0.5) discard;
  float n = 0.0;
  for (int dx = -1; dx <= 1; dx++) {
    for (int dy = -1; dy <= 1; dy++) {
      n = max(n, alphaAt(tex, uv + vec2(float(dx), float(dy)) * texel));
    }
  }
  if (n < 0.5) discard;
  return color;
}

uniform vec3 fromC[8];
uniform vec3 toC[8];
vec4 effect(vec4 color, Image tex, vec2 uv, vec2 sc) {
  vec4 c = Texel(tex, uv);
  vec3 rgb = c.rgb;
  for (int i = 0; i < 8; i++) {
    if (distance(c.rgb, fromC[i]) < 0.02) rgb = toC[i];
  }
  return vec4(rgb, c.a) * color;
}

vec4 effect(vec4 color, Image tex, vec2 uv, vec2 sc) {
  return vec4(color.rgb, color.a * step(0.5, Texel(tex, uv).a));
}

vec4 effect(vec4 color, Image tex, vec2 uv, vec2 sc) {
  return vec4(color.rgb, color.a * step(0.5, Texel(tex, uv).a));
}

extern float fill;
extern float sheetW;
extern vec3 dimLight;
extern vec3 dimWhite;
extern vec3 front;
extern float fromTip;
extern float originalMix;
vec4 effect(vec4 color, Image tex, vec2 uv, vec2 sc) {
  vec4 p = Texel(tex, uv);
  if (p.a < 0.5) return vec4(0.0);
  if (max(p.r, max(p.g, p.b)) < 0.3) return vec4(p.rgb, 1.0);
  float lx = mod(floor(uv.x * sheetW), 16.0);
  if (fromTip > 0.5) lx = 15.0 - lx;
  if (lx < fill - 1.0) return vec4(p.rgb, 1.0);
  if (lx < fill) return vec4(front, 1.0);
  if (p.r > 0.95 && p.g > 0.95 && p.b > 0.95) return vec4(mix(dimWhite, p.rgb, originalMix), 1.0);
  return vec4(mix(dimLight, p.rgb, originalMix), 1.0);
}

extern vec2 texelStep;
vec4 effect(vec4 color, Image tex, vec2 uv, vec2 sc) {
  if (Texel(tex, uv).a < 0.5) return vec4(0.0);
  float n = min(min(Texel(tex, uv + vec2(texelStep.x, 0.0)).a, Texel(tex, uv - vec2(texelStep.x, 0.0)).a),
                min(Texel(tex, uv + vec2(0.0, texelStep.y)).a, Texel(tex, uv - vec2(0.0, texelStep.y)).a));
  return n < 0.5 ? color : vec4(0.0);
}

vec4 effect(vec4 color, Image tex, vec2 uv, vec2 sc) {
  return vec4(color.rgb, color.a * step(0.5, Texel(tex, uv).a));
}

extern vec2 sheetSize;
extern vec2 frameOrigin;
extern vec2 frameSize;
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 screen) {
  vec4 src=Texel(tex,tc);
  if(src.a<=0.001) return vec4(0.0);
  vec2 p=floor(tc*sheetSize-frameOrigin);
  vec2 texel=1.0/sheetSize;
  float left=p.x<1.0 ? 0.0 : Texel(tex,tc-vec2(texel.x,0.0)).a;
  float right=p.x>=frameSize.x-1.0 ? 0.0 : Texel(tex,tc+vec2(texel.x,0.0)).a;
  float up=p.y<1.0 ? 0.0 : Texel(tex,tc-vec2(0.0,texel.y)).a;
  float down=p.y>=frameSize.y-1.0 ? 0.0 : Texel(tex,tc+vec2(0.0,texel.y)).a;
  float rim=1.0-min(min(left,right),min(up,down));
  float facet=step(5.0,mod(p.x+p.y*2.0,13.0));
  float frost=step(8.0,mod(p.x*7.0+p.y*11.0,23.0));
  float shine=1.0-step(1.0,mod(p.x-p.y+frameSize.y,11.0));
  float luma=dot(src.rgb,vec3(0.299,0.587,0.114));
  vec3 ice=mix(vec3(0.17,0.51,0.77),vec3(0.57,0.86,0.98),luma*.65+facet*.35);
  ice=mix(ice,vec3(0.90,0.98,1.0),clamp(rim*.75+shine*.5+frost*.10,0.0,.9));
  return vec4(ice,src.a*color.a);
}

extern number dim;
vec4 effect(vec4 color, Image mask, vec2 uv, vec2 sc) {
  return vec4(0.018,0.012,0.065,dim*(1.0-Texel(mask,uv).a));
}

extern number clock;
extern number spread;
extern number authority;
vec4 effect(vec4 color, Image texture, vec2 uv, vec2 sc) {
  // Continuous coordinates keep the light soft independently of the
  // pixel-art body. Scaling around UV center makes it emerge outward.
  vec2 p=(uv*2.0-1.0)/spread;
  float r=length(p);
  float angle=atan(p.y,p.x);
  float cloud=0.65+0.18*sin(p.x*9.0+p.y*5.0+clock)
    +0.12*sin(p.y*13.0-p.x*4.0-clock*0.7);
  float core=exp(-r*r*6.0);
  float mist=exp(-r*r*4.4)*cloud;
  float rays=pow(abs(cos(angle*3.0+clock*0.13+r*1.4)),18.0)
    *exp(-r*3.4)*smoothstep(0.04,0.15,r);
  float crown=pow(abs(cos(angle*4.0-clock*0.09)),32.0)
    *exp(-r*3.8)*smoothstep(0.10,0.24,r);
  float edge=1.0-smoothstep(0.58,0.96,r);
  vec3 hue=mix(vec3(0.60,0.36,1.0),vec3(0.36,0.86,1.0),
    0.5+0.5*sin(angle*2.0+clock*0.2));
  hue=mix(hue,vec3(1.0,0.95,0.78),min(1.0,core*(0.85+authority*0.15)));
  float radiance=(mist*0.88+core*0.42+rays*1.65+crown*0.95)
    *(0.95+0.05*sin(clock*1.7))*(1.0+authority*0.38);
  return vec4(hue,min(1.0,radiance)*edge*color.a);
}

extern vec2 u_sheet;
extern vec4 u_frame;
extern number u_time;
extern number u_pressure;
float maskAt(Image tex, vec2 p) {
  if (p.x < 0.0 || p.y < 0.0 || p.x >= u_frame.z || p.y >= u_frame.w) return 0.0;
  return Texel(tex, (u_frame.xy + p + vec2(0.5)) / u_sheet).a;
}
vec4 effect(vec4 color, Image tex, vec2 uv, vec2 screen) {
  vec4 source = Texel(tex, uv);
  if (source.a <= 0.0) return vec4(0.0);
  vec2 p = floor(uv*u_sheet)-u_frame.xy;
  float edge = 1.0-min(min(maskAt(tex,p+vec2(1.0,0.0)),maskAt(tex,p-vec2(1.0,0.0))),
                      min(maskAt(tex,p+vec2(0.0,1.0)),maskAt(tex,p-vec2(0.0,1.0))));
  // A slow sheen and staggered, softly breathing highlights make the
  // authored sprite sparkle without rapid flashing or changing its mask.
  float wave = 0.5+0.5*sin((p.y+p.x*0.55)*0.22-u_time*0.85);
  float sweep = smoothstep(0.80,1.0,wave);
  float seed = fract(sin(dot(p,vec2(12.9898,78.233)))*43758.5453);
  float twinkle = 0.5+0.5*sin(u_time*0.95+seed*23.0);
  float glint = step(0.975,seed)*pow(twinkle,4.0);
  float breath = 0.85+0.15*sin(u_time*0.9);
  vec3 tint = mix(vec3(0.48,0.35,1.0),vec3(1.0,0.84,0.43),wave);
  tint = mix(tint,vec3(1.0,0.97,0.82),glint);
  tint=mix(tint,vec3(1.0,0.96,0.84),u_pressure*0.18);
  float intensity = min(0.78+0.17*u_pressure,
    (0.06+0.28*sweep+0.12*edge+0.72*glint)*breath*(1.0+0.65*u_pressure));
  return vec4(tint,source.a*color.a*intensity);
}

extern vec2 u_size;
extern vec2 u_mouth;
extern number u_facing;
extern number u_charge;
extern number u_strength;
extern number u_flash;
extern number u_time;
extern number u_pixel;

vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
  vec2 p = (floor(tc * u_size / u_pixel) + vec2(0.5)) * u_pixel;
  vec2 d = (p - u_mouth) / max(1.0, u_size.y);
  float along = d.x * u_facing;
  // Light radiates from the jet across the view, widening ahead of it.
  float forward = smoothstep(-0.12, 0.18, along);
  float plume = exp(-dot(d * vec2(1.1, 2.5), d * vec2(1.1, 2.5)) * 4.0);
  float mouth = exp(-dot(d,d) * 65.0);
  vec2 q = abs(tc * 2.0 - 1.0);
  float edge = smoothstep(0.24, 1.0, max(q.x, q.y));
  // One smooth exposure pulse follows the confirmed hit, never a strobe.
  float light = u_strength * (0.055 + plume * (0.13 + forward * 0.12))
    + u_flash * (0.15 + mouth * 0.12);
  float dark = (u_charge * 0.30 + u_strength * 0.20)
    * (0.38 + edge * 0.62) * (1.0 - mouth * 0.75);
  // Subtle moving soot in the outer vignette, not geometry on the ground.
  float soot = 0.5 + 0.5 * sin(tc.x * 19.0 + tc.y * 13.0 - u_time * 2.0);
  dark *= 0.92 + soot * 0.08;
  float alpha = clamp(light + dark * (1.0-light), 0.0, 0.65);
  vec3 fire = mix(vec3(1.0, 0.22, 0.015), vec3(1.0, 0.86, 0.48), u_flash);
  vec3 rgb = (fire * light + vec3(0.028, 0.006, 0.009) * dark * (1.0-light))
    / max(0.001, alpha);
  return vec4(rgb, alpha * color.a);
}

extern number u_strength;
extern number u_impact;
extern vec2 u_size;
extern vec2 u_mouth;
extern number u_length;
extern number u_width;
extern number u_pixel;
extern number u_facing;

vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
  vec2 p = (floor(tc * u_size / u_pixel) + vec2(0.5)) * u_pixel;
  vec2 delta = p - u_mouth;
  float along = delta.x * u_facing;
  float axis = clamp(along, 0.0, u_length);
  // Fixed, forward-facing firelight surrounding the current flame.
  // There is no expanding radius, shockwave or travelling screen front.
  float spread = mix(u_pixel * 3.0, u_width, axis / max(1.0, u_length));
  float distance = length(vec2((along - axis) * 0.85, delta.y));
  float jetLight = exp(-pow(distance / max(1.0, spread), 2.0) * 1.6);
  float facingMask = smoothstep(-u_pixel * 6.0, u_pixel * 2.0, along);
  float fire = jetLight * facingMask * u_strength * 0.18;
  vec2 q = abs(tc * 2.0 - 1.0);
  float edge = smoothstep(0.40, 1.0, max(q.x, q.y));
  // The entire view briefly responds to the jet's light, then clears as
  // that exact flame dies down. No independent green border or strobing.
  float darkness = edge * u_strength * 0.10;
  float exposure = u_strength * 0.035 + u_impact * 0.055;
  float light = fire + exposure;
  float alpha = light + darkness * (1.0 - light);
  vec3 lit = mix(vec3(0.063, 0.741, 0.580),
    vec3(0.647, 0.973, 0.855), 0.35 + u_impact * 0.3);
  vec3 rgb = (lit * light + vec3(0.005, 0.015, 0.012)
    * darkness * (1.0 - light)) / max(0.001, alpha);
  return vec4(rgb, alpha * color.a);
}

extern vec4 u_frame;
extern vec2 u_frameSize;
extern vec4 u_bounds;
extern number u_height;
extern number u_time;
extern number u_alpha;
extern vec3 u_dark;
extern vec3 u_mid;
extern vec3 u_bright;
extern vec3 u_core;
extern number u_heat;

float spriteAlpha(Image tex, vec2 p) {
  // Never sample another frame, even when the flame extends outside this
  // frame's rectangle or a weapon reaches the edge of the source sheet.
  if (p.x < 0.0 || p.y < 0.0 || p.x >= u_frameSize.x
      || p.y >= u_frameSize.y) return 0.0;
  vec2 uv = (floor(p) + vec2(0.5)) / u_frameSize;
  return Texel(tex, u_frame.xy + uv * u_frame.zw).a;
}

vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
  // One source-pixel grid, transformed by the very same scale/flip as the
  // unit. Wide and tall sprites keep their proportions and crisp edges.
  vec2 p = floor(tc * u_frameSize) + vec2(0.5);
  vec2 body = (p - u_bounds.xy) / max(u_bounds.zw, vec2(1.0));
  float own = spriteAlpha(tex, p);
  float phase = u_time * 5.4;
  float columns = clamp(u_bounds.z / 3.5, 3.0, 10.0);
  float wave = sin(body.x * columns * 6.283 + phase
    + sin(body.x * 8.0 - phase * 0.71));
  float flicker = 0.5 + 0.5 * sin(body.x * 17.0
    + body.y * 13.0 + phase * 1.35);
  float height = u_height * (0.48 + 0.38 * (0.5 + 0.5 * wave)
    + 0.14 * flicker);
  float fire = 0.0;
  // Pull alpha upward from the actual body, with increasingly wandering,
  // fading tips. The enlarged mesh lets fire rise beyond the source quad.
  for (int i = 1; i <= 8; i++) {
    float rise = float(i) / 8.0;
    float sway = sin(phase * 0.83 + body.x * 12.0
      - rise * 3.8) * rise * 1.65;
    float fuel = spriteAlpha(tex, p + vec2(sway, rise * height));
    fire = max(fire, fuel * (1.0 - rise * 0.76));
  }
  float tongue = smoothstep(0.015, 0.72, fire) * (1.0 - own);
  float flow = 0.5 + 0.5 * sin(body.y * 18.0 + phase * 1.6
    + wave * 1.4);
  float heat = own * (0.09 + 0.23 * pow(flow, 3.0))
    * (0.65 + 0.35 * flicker);
  float alpha = (tongue * 0.9 + heat * u_heat) * u_alpha * color.a;
  float energy = clamp(fire * 0.85 + flow * 0.30, 0.0, 1.0);
  vec3 flame = mix(u_dark, u_mid, smoothstep(0.1, 0.45, energy));
  flame = mix(flame, u_bright, smoothstep(0.4, 0.8, energy));
  flame = mix(flame, u_core, smoothstep(0.85, 1.0, energy) * 0.65);
  return vec4(flame, alpha);
}

vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
  if (Texel(tex, tc).a < 0.01) discard;
  return vec4(1.0);
}

extern float u_time;
extern vec2 u_origin;
extern vec2 u_size;
extern float u_pixel;
extern float u_seed;

// 2D procedural hash
float hash(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

// Smooth 2D Hermite Value Noise
float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),
    mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x),
    u.y
  );
}

// 4-octave smooth FBM
float fbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  mat2 rot = mat2(cos(0.5), sin(0.5), -sin(0.5), cos(0.5));
  for (int i = 0; i < 4; i++) {
    v += a * noise(p);
    p = rot * p * 2.05 + vec2(1.4, 3.2);
    a *= 0.5;
  }
  return v;
}

vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
  // Snap strictly to virtual pixel grid
  float pSize = max(1.0, u_pixel);
  vec2 gridCoord = floor((sc - u_origin) / pSize);
  vec2 nativeRes = max(vec2(1.0, 1.0), floor(u_size / pSize));
  vec2 uv = gridCoord / nativeRes;

  // Slow, tranquil, organic fluid time
  float t = u_time * 0.06;
  float s = u_seed * 7.31;

  // 2D Domain Warping for fluid-like organic cosmic gas billows
  vec2 p = uv * vec2(2.5, 2.0) + vec2(s, s * 0.61);

  vec2 q = vec2(
    fbm(p + vec2(0.0, 0.0) + t * 0.28),
    fbm(p + vec2(3.2, 1.7) - t * 0.22)
  );

  vec2 r = vec2(
    fbm(p + 1.5 * q + vec2(1.7, 4.2) + t * 0.18),
    fbm(p + 1.5 * q + vec2(5.3, 2.1) - t * 0.16)
  );

  float rawGas = fbm(p + 1.7 * r + vec2(t * 0.12, -t * 0.10));

  // Lower altitude position: centered around mid-lower skyline
  float spineCenter = 0.67 - 0.12 * (uv.x - 0.5) 
    + 0.07 * sin(uv.x * 3.14159 * 1.3 + t * 0.35 + s)
    + 0.035 * cos(uv.x * 3.14159 * 2.5 - t * 0.25);

  float distFromSpine = abs(uv.y - spineCenter);

  // Rich, broad stream mask (voluminous cloud spread)
  float streamMask = smoothstep(0.44, 0.06, distFromSpine);

  // Subtle cosmic void dips (natural variations without emptying the sky)
  float voidNoise = fbm(uv * vec2(1.5, 1.2) + vec2(s * 1.2, t * 0.06));
  float clusterBreak = 0.50 + 0.50 * smoothstep(0.18, 0.68, voidNoise);

  // Long, bending filaments break up the round FBM billows. Each strand
  // follows the main spine but curls at a different rate, creating the
  // layered, mysterious folds seen in a distant cosmic veil.
  float filamentCurveA = spineCenter - 0.115
    + 0.042 * sin(uv.x * 6.28318 * 1.35 + t * 2.40 + s);
  float filamentCurveB = spineCenter + 0.025
    + 0.034 * sin(uv.x * 6.28318 * 1.85 - t * 1.80 + s * 0.63);
  float filamentCurveC = spineCenter + 0.145
    + 0.027 * cos(uv.x * 6.28318 * 1.20 + t * 2.10 + s * 1.31);
  float filamentA = 1.0 - smoothstep(0.012, 0.044,
    abs(uv.y - filamentCurveA));
  float filamentB = 1.0 - smoothstep(0.011, 0.040,
    abs(uv.y - filamentCurveB));
  float filamentC = 1.0 - smoothstep(0.012, 0.043,
    abs(uv.y - filamentCurveC));
  float alongGrain = 0.68 + 0.32 * noise(vec2(
    uv.x * 7.0 - t * 0.75, uv.y * 1.3 + s));
  float filaments = (filamentA * 0.72 + filamentB
    + filamentC * 0.58) * alongGrain;

  // A slim moving hollow keeps the bands separated instead of letting the
  // whole formation read as one soft, circular cloud.
  float hollowCurve = spineCenter - 0.025
    + 0.038 * sin(uv.x * 6.28318 * 1.10 - t * 1.65 + s * 0.37);
  float hollow = 1.0 - smoothstep(0.007, 0.026,
    abs(uv.y - hollowCurve));

  // Generous sky coverage bounds
  float skyMask = smoothstep(0.04, 0.20, uv.y) * smoothstep(0.92, 0.55, uv.y);

  float density = (rawGas * 1.28 + 0.16 * (r.x + q.y) - 0.13)
    * streamMask * clusterBreak * skyMask;
  density += filaments * streamMask * skyMask * 0.34;
  density -= hollow * streamMask * 0.10;

  // Crisp, solid 4-tier pixel art bands (100% matched to reference image)
  vec3 cOuter = vec3(45.0 / 255.0, 49.0 / 255.0, 80.0 / 255.0);   // #2d3150
  vec3 cMid   = vec3(70.0 / 255.0, 69.0 / 255.0, 116.0 / 255.0);  // #464574
  vec3 cCore  = vec3(112.0 / 255.0, 98.0 / 255.0, 158.0 / 255.0); // #70629e
  vec3 cLight = vec3(161.0 / 255.0, 149.0 / 255.0, 203.0 / 255.0); // #a195cb

  if (density < 0.15) {
    return vec4(0.0);
  } else if (density < 0.35) {
    return vec4(cOuter, 0.95 * color.a);
  } else if (density < 0.54) {
    return vec4(cMid, 0.95 * color.a);
  } else if (density < 0.72) {
    return vec4(cCore, 0.95 * color.a);
  } else {
    return vec4(cLight, color.a);
  }
}

extern number time;
vec3 hue(float h) { return clamp(abs(mod(h * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0); }
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
  float nx = tc.x * 2.0 - 1.0;
  float q = nx / 0.52;
  float body = exp(-q * q) * (1.0 - smoothstep(0.75, 1.0, abs(nx)));
  float r = nx / 0.13;
  float heart = exp(-r * r);
  vec3 col = mix(hue(tc.y / 170.0 - time * 0.3 + nx * 0.1), vec3(1.0), 0.05 + 0.25 * heart);
  return vec4(col, body * color.a);
}

extern number mode;
extern number time;
extern number len;
extern number seed;
extern vec3 tint;
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
  vec2 p = tc * 2.0 - 1.0;
  if (mode < 0.5) {
    float bx = p.x / 0.45;
    float hx = p.x / 0.12;
    float body = exp(-bx * bx);
    float heart = exp(-hx * hx);
    float y = tc.y * len;
    float flow = 0.72 + 0.28 * sin(y / 21.0 - time * 8.0 + p.x * 3.0 + seed) * sin(y / 57.0 - time * 3.5);
    float top = smoothstep(0.0, 0.4, tc.y);
    vec3 col = mix(tint, vec3(1.0), heart * 0.85);
    float a = (body * 0.8 * flow + heart * 0.45) * top * (1.0 - smoothstep(0.8, 1.0, abs(p.x)));
    return vec4(col, a) * color;
  }
  float r = length(p);
  float ang = atan(p.y, p.x);
  if (mode < 1.5) {
    float ray = pow(0.5 + 0.5 * cos(ang * 12.0 + time * 0.5 + sin(ang * 3.0 + seed) * 1.3), 7.0);
    float ray2 = pow(0.5 + 0.5 * cos(ang * 7.0 - time * 0.3 + seed * 2.0), 12.0);
    float fall = exp(-r * 2.4) * (1.0 - smoothstep(0.8, 1.0, r));
    float cr = r / 0.17;
    float core = exp(-cr * cr);
    float sr = r / 0.45;
    float soft1 = exp(-sr * sr);
    vec3 col = mix(tint, vec3(1.0), clamp(core * 0.9 + 0.25 * ray, 0.0, 1.0));
    float a = max(ray, ray2 * 0.75) * fall + core * 0.85 + soft1 * 0.4;
    return vec4(col, min(a, 1.0)) * color;
  }
  if (mode < 2.5) {
    float d = (r - 0.78) / 0.055;
    float band = exp(-d * d);
    float d2 = (r - 0.78) / 0.2;
    float halo = exp(-d2 * d2) * 0.4;
    float run = 0.55 + 0.45 * pow(0.5 + 0.5 * cos(ang * 2.0 - time * 2.6 + seed), 4.0);
    vec3 col = mix(tint, vec3(1.0), band * 0.65 * run);
    float a = (band * run + halo) * (1.0 - smoothstep(0.94, 1.0, r));
    return vec4(col, a) * color;
  }
  // a wing: a few broad, overlapping feathers of light fanning up and out
  // from its root (bottom left), their tips curving, soft all over
  vec2 q = vec2(tc.x, 1.0 - tc.y) - vec2(0.04, 0.12);
  float rr = length(q);
  float an = atan(q.y, q.x) - 0.25 * rr;
  float u = clamp((an + 0.1) / 1.5, 0.0, 1.0);
  float f = u * 5.0;
  float fi = floor(f);
  float fr = f - fi;
  float vane = exp(-((fr - 0.5) / 0.38) * ((fr - 0.5) / 0.38));
  float lenf = 0.58 + 0.4 * sin(3.14159 * (fi + 0.5) / 5.0);
  float along = rr / lenf;
  float tip = 1.0 - smoothstep(0.7, 1.0, along);
  float root = smoothstep(0.0, 0.15, rr);
  float inside = smoothstep(-0.12, -0.02, an) * (1.0 - smoothstep(1.32, 1.42, an));
  float shimmer = 0.85 + 0.15 * sin(along * 7.0 - time * 2.5 + fi);
  float body = exp(-((rr - 0.25) / 0.35) * ((rr - 0.25) / 0.35));
  vec3 col = mix(tint, vec3(1.0), 0.55 * (1.0 - along) + 0.25 * vane);
  float a = (vane * 0.7 + body * 0.35) * tip * root * inside * shimmer;
  return vec4(col, a) * color;
}

extern number mode;
extern number time;
extern number len;
vec3 hue(float h) {
  return clamp(abs(mod(h * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);
}
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
  float nx = tc.x * 2.0 - 1.0;
  float ax = abs(nx);
  float y = tc.y * len;
  float body = exp(-pow(nx / 0.52, 2.0)) * (1.0 - smoothstep(0.75, 1.0, ax));
  if (mode < 0.5) {
    float heart = exp(-pow(nx / 0.13, 2.0));
    vec3 col = mix(hue(y / 170.0 - time * 0.3 + nx * 0.1), vec3(1.0), 0.05 + 0.25 * heart);
    return vec4(col, body) * color;
  }
  if (mode < 1.5) {
    float band = 0.5 + 0.5 * sin(y / 34.0 - nx * 2.5 - time * 3.2);
    vec3 col = mix(vec3(1.0, 0.95, 1.0), hue(y / 300.0 + nx * 0.3 - time * 0.18), 0.68 * band);
    return vec4(col, body * (0.7 + 0.3 * band)) * color;
  }
  if (mode < 2.5) {
    float spread = smoothstep(0.1, 1.0, tc.y);
    float x = nx / mix(0.3, 1.0, spread) + 0.05 * spread * sin(y / 40.0 - time * 2.5);
    float prof = exp(-pow(x / 0.55, 2.0)) * (1.0 - smoothstep(0.8, 1.0, abs(x)));
    vec3 col = mix(vec3(1.0), hue(0.78 * clamp((x + 0.85) / 1.7, 0.0, 1.0)), 0.62 * spread);
    return vec4(col, prof) * color;
  }
  float wob = 0.035 * sin(y / 55.0 - time * 2.2 + (nx < 0.0 ? 0.0 : 1.7));
  float fringe = exp(-pow((ax - 0.64 - wob) / 0.11, 2.0));
  float k = smoothstep(0.52, 0.78, ax);
  float h = nx < 0.0 ? mix(0.14, -0.03, k) : mix(0.5, 0.75, k);
  vec3 fc = mix(hue(h), vec3(1.0), 0.35);
  float wa = exp(-pow(nx / 0.42, 2.0)) * 0.75;
  float fa = fringe * 0.85;
  vec3 col = (vec3(1.0, 0.9, 0.98) * wa + fc * fa) / max(0.001, wa + fa);
  return vec4(col, min(1.0, wa + fa) * (1.0 - smoothstep(0.85, 1.0, ax))) * color;
}
